// Stages the QuickJS WebAssembly engine (quickjs-emscripten, MIT; ~490 KB)
// that runs plugin logic (src/plugins/runtime/sandbox.ts) into
// public/quickjs/, so the plugin worker loads it SAME-ORIGIN (the app's CSP
// allows no CDN) and only when a plugin is loaded. public/quickjs/ is
// git-ignored, regenerated by predev/prebuild, and not in the startup bundle
// nor the service worker's precache.
import { copyFileSync, existsSync, mkdirSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const require = createRequire(join(here, "..", "package.json"));
let src = "";
try {
  src = join(dirname(require.resolve("@jitl/quickjs-wasmfile-release-sync/package.json")), "dist", "emscripten-module.wasm");
} catch {
  /* not installed */
}
const outDir = join(here, "..", "public", "quickjs");
if (!src || !existsSync(src)) {
  console.warn("copy-quickjs: @jitl/quickjs-wasmfile-release-sync not installed — plugins will fail to load");
  process.exit(0);
}
mkdirSync(outDir, { recursive: true });
const dest = join(outDir, "emscripten-module.wasm");
if (!existsSync(dest) || statSync(dest).size !== statSync(src).size) copyFileSync(src, dest);
console.log(`copy-quickjs: emscripten-module.wasm → public/quickjs/ (${(statSync(src).size / 1e6).toFixed(2)} MB)`);
